using Azurite.NormalEditor.Entry;

static class ObservationBridgeChecks
{
    internal static void Run(Action<string,Action> test,Action<bool,string> need)
    {
        foreach(var stage in new[]{"before-start","before-finalizer","same-frame"})test("deferred observation never reads fields "+stage,()=>{var f=new Fixture();if(stage=="before-finalizer"){var token=f.Gate.StartEntered(f.Stamp(10,1));f.Gate.StartReturned(token,f.Stamp(10,2),true);}else if(stage=="same-frame")f.Start();var stamp=f.Stamp(stage=="same-frame"?10:11,5,0);var tracker=new CatalogTickCallbacks(f.Gate);var frame=tracker.Enter(stamp,200);tracker.Returned(frame,stamp,200,true);need(tracker.TryComplete(frame,stamp,200,null),"actual callback tracker refused early normal Update");var reads=0;f.Gate.ObserveTick(stamp,()=>{reads++;return f.Observation;},()=>{reads++;return f.Observation;});need(reads==0&&!f.Gate.Ready&&f.Gate.Failure is null,"unadmitted field delegate ran");});
        test("actual observation bridge reads only after authentic Start and later completed Update",()=>{var events=new List<CatalogEvidence>();var order=new List<string>();var gate=new CatalogReadiness(Fixture.Binding,e=>{events.Add(e);if(e.Kind=="catalog-ready")order.Add("ready");});var f=new Fixture(gate,events);f.Start();var stamp=f.Stamp(11,5,0);var tracker=new CatalogTickCallbacks(gate);var frame=tracker.Enter(stamp,200);tracker.Returned(frame,stamp,200,true);need(tracker.TryComplete(frame,stamp,200,null),"original Update did not complete");gate.ObserveTick(stamp,()=>{order.Add("read");return f.Observation;},()=>{order.Add("guard-readback");return f.Observation;});need(gate.Ready&&order.SequenceEqual(new[]{"read","guard-readback","ready"}),"read/guard/evidence order differs");});
        foreach(var state in new[]{"ready","failed"})test("deferred observation stops field sampling after "+state,()=>{var f=new Fixture();f.Start();if(state=="ready")f.Tick();else f.Gate.Reject("failed run",f.Stamp(11,5));var reads=0;f.Gate.ObserveTick(f.Stamp(12,6,0),()=>{reads++;return f.Observation;},()=>{reads++;return f.Observation;});need(reads==0,"terminal observer sampled native fields");});
        foreach(var field in new[]{"run","process","managed-thread","native-thread"})test("deferred observation rejects "+field+" before field reads",()=>{var f=new Fixture();f.Start();var stamp=f.Stamp(11,5,0);stamp=field switch{"run"=>stamp with{RunId="11111111-1111-1111-1111-111111111111"},"process"=>stamp with{ProcessId=43},"managed-thread"=>stamp with{ManagedThreadId=9},_=>stamp with{NativeThreadId=99}};var reads=0;f.Gate.ObserveTick(stamp,()=>{reads++;return f.Observation;},()=>{reads++;return f.Observation;});need(reads==0&&f.Gate.Failure is not null&&!f.Gate.Ready,"foreign callback read native fields");});
        test("deferred observation refuses expired callback before any field read",()=>{var f=new Fixture();f.Start();var reads=0;f.Gate.ObserveTick(f.Stamp(11,101,0),()=>{reads++;return f.Observation;},()=>{reads++;return f.Observation;});need(reads==0&&f.Gate.Failure is not null,"late callback read native fields");});
        test("deferred observation cannot switch frame before native idle guard",()=>{var f=new Fixture();f.Start();var guards=0;f.Gate.ObserveTick(f.Stamp(11,5,0),()=>f.Observation with{Stamp=f.Stamp(12,6)},()=>{guards++;return f.Observation;});need(guards==0&&f.Gate.Failure is not null&&!f.Gate.Ready,"field read from another frame reached guard");});
        test("field delegate failure latches without invoking idle guard",()=>{var f=new Fixture();f.Start();var guards=0;f.Gate.ObserveTick(f.Stamp(11,5,0),()=>throw new Exception("field read failed"),()=>{guards++;return f.Observation;});need(guards==0&&f.Gate.Failure!.Contains("field read failed")&&!f.Gate.Ready,"failed read continued to guard");});
        test("field delegate reentry cannot sample twice or reach idle guard",()=>{var f=new Fixture();f.Start();var reads=0;var guards=0;var stamp=f.Stamp(11,5,0);f.Gate.ObserveTick(stamp,()=>{reads++;f.Gate.ObserveTick(stamp,()=>{reads++;return f.Observation;},()=>{guards++;return f.Observation;});return f.Observation;},()=>{guards++;return f.Observation;});need(reads==1&&guards==0&&f.Gate.Failure is not null&&!f.Gate.Ready,"field read reentry accepted");});
    }
}
